(assert (= "1.12.6" (clojure-version)))
(let [source "(let [^long x (identity 5.5)] [x (max x 1) (min x 1) (max x) (min x) (max x 1 2)])" expected "[5.5 5 1 5.5 5.5 5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^double x (identity 5)] [x (max x 1.0) (min x 6.0) (max x 6) (min x 6)])" expected "[5 5.0 5.0 6 5.0]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^double x (identity -0.0)] [(/ 1.0 (max x 0.0)) (/ 1.0 (max 0.0 x)) (/ 1.0 (min x 0.0)) (/ 1.0 (min 0.0 x))])" expected "[##Inf ##Inf ##-Inf ##-Inf]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^double x (identity -0.0)] [(/ 1.0 (max x (identity 0.0))) (/ 1.0 (max (identity 0.0) x)) (/ 1.0 (min x (identity 0.0))) (/ 1.0 (min (identity 0.0) x))])" expected "[##Inf ##-Inf ##Inf ##-Inf]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [f (identity max) g (identity min)] [(/ 1.0 (f -0.0 0.0)) (/ 1.0 (f 0.0 -0.0)) (/ 1.0 (g -0.0 0.0)) (/ 1.0 (g 0.0 -0.0))])" expected "[##Inf ##-Inf ##Inf ##-Inf]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 5.5) ^double y (identity 6)] [(max x y) (min x y) (max x (identity 6)) (min x (identity 6))])" expected "[6.0 5 6 5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 5.5)] [(max x 6) (max x 6.0) (max x 1 2.0) (min x 6.0) (max x 1 6) (min x 6 1) (max x (identity 6) 7.0)])" expected "[6 6.0 5 5 6 1 7.0]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 1.0E30) events (atom [])] [(try (max x 1 (do (swap! events conj :later) 1)) (catch Throwable e :cast-error)) @events])" expected "[:cast-error []]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 1.0E30) events (atom [])] [(try (min x 1 (do (swap! events conj :later) 1)) (catch Throwable e :cast-error)) @events])" expected "[:cast-error []]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "[((fn ^long [] (max 1 2.0))) ((fn ^double [] (max 1))) ((fn ^long [] (min 1.5)))]" expected "[2 1.0 1]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^double x (identity ##NaN)] [(max x 1.0) (min 1.0 x) (max x (identity 1)) (min (identity 1) x)])" expected "[##NaN ##NaN ##NaN ##NaN]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [f (identity max) g (identity min)] [(max nil ##NaN) (min ##NaN nil) (f nil ##NaN) (g ##NaN nil)])" expected "[##NaN ##NaN ##NaN ##NaN]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 5.5) ^double y (identity ##NaN)] [(max x y) (min y x) (max x (identity ##NaN)) (min (identity ##NaN) x)])" expected "[##NaN ##NaN ##NaN ##NaN]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "[(max 9007199254740993 9007199254740995) (min 9007199254740993 9007199254740995) (max 9007199254740993 9007199254740992.0) (min 9007199254740992.0 9007199254740993)]" expected "[9007199254740995 9007199254740993 9.007199254740992E15 9007199254740993]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [f (identity max) g (identity min)] [(try (max :x 1) (catch Throwable e :error)) (try (f :x 1) (catch Throwable e :error)) (try (min 1 nil) (catch Throwable e :error)) (try (g 1 nil) (catch Throwable e :error))])" expected "[:error :error :error :error]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(with-redefs [max (fn [a b] :replaced)] [(max 1 2) ((identity max) 1 2)])" expected "[2 :replaced]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [f (identity max) ^long x (identity 5.5) events (atom [])] [(f x 1 (do (swap! events conj :later) 2)) @events])" expected "[5.5 [:later]]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 5.5) y (max x 1)] [y (+ y 1) (min y 6)])" expected "[5 6 5]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^double x (identity 5) y (max x 6.0)] [y (+ y 1) (min y 7.0)])" expected "[6.0 7.0 6.0]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 5.5) y (max x 6.0)] [y (+ y 1) (min y 7)])" expected "[6.0 7.0 6.0]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 1.0E30) events (atom [])] [(try (max x (zero? (do (swap! events conj :later) 0))) (catch Throwable e :number-error)) @events])" expected "[:number-error [:later]]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [^long x (identity 5.5) ^double y (identity -0.0)] [(max x) (min y) (max x 1.0 -1.0) (min y 1.0 0.0)])" expected "[5.5 -0.0 5 -0.0]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(loop [i 0 acc 0] (if (< i 5) (recur (inc i) (max acc (min i 3))) acc))" expected "3" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
(let [source "(let [result (loop [i 0 acc -0.0] (if (< i 5) (recur (inc i) (max acc (min (double i) 0.0))) acc))] (/ 1.0 result))" expected "##Inf" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= expected actual)))
